[InitializeOnLoad]public static class JoinExistingCanalEdge{static JoinExistingCanalEdge(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("JoinExistingCanalEdge.request"))return;File.Delete("JoinExistingCanalEdge.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/JoinExistingCanalEdge.txt",e.ToString());Debug.LogException(e);}}static string K(Vector3 p)=>Mathf.RoundToInt(p.x*100)+","+Mathf.RoundToInt(p.y*100)+","+Mathf.RoundToInt(p.z*100);static Vector3 Closest(Vector3 p,Vector3 a,Vector3 b){var d=b-a;return a+d*Mathf.Clamp01(Vector3.Dot(p-a,d)/d.sqrMagnitude);}static void Run(){var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roads=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var shore=roads.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Canal1");Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeDirectCanalJoin");File.Copy(AssetDatabase.GetAssetPath(shore.sharedMesh),"FinalEnvironmentRoadBackup/BeforeDirectCanalJoin/Canal Mesh.asset",true);var edgesMethod=typeof(BeachPromenadeJoin).GetMethod("Edges",BindingFlags.NonPublic|BindingFlags.Static);Func<MeshFilter,List<Vector3[]>> Edges=f=>((System.Collections.IEnumerable)edgesMethod.Invoke(null,new object[]{f})).Cast<object>().Select(e=>new[]{(Vector3)e.GetType().GetField("a").GetValue(e),(Vector3)e.GetType().GetField("b").GetValue(e)}).ToList();var paving=roads.GetComponentsInChildren<MeshFilter>().Where(f=>!f.name.ToLower().Contains("beach promenade sidewalk joins")&&f.GetComponent<Renderer>()&&f.GetComponent<Renderer>().sharedMaterials.Any(m=>m&&(m.name=="Pathways"||m.name=="Road Atlas"||m.name.StartsWith("City PNG")))).SelectMany(Edges).ToArray();var boundary=Edges(shore).Where(e=>e.All(p=>p.x>=140&&p.x<165&&p.z>-430&&p.z<610)&&Mathf.Abs((e[1]-e[0]).normalized.z)>.85f).ToArray();var moves=new Dictionary<string,Vector3>();foreach(var edge in boundary){var dir=(edge[1]-edge[0]).normalized;foreach(var p in edge){var candidates=paving.Where(q=>Mathf.Abs(Vector3.Dot(dir,(q[1]-q[0]).normalized))>.85f).Select(q=>Closest(p,q[0],q[1])).Where(q=>q.x>=p.x-.2f&&Mathf.Abs(q.y-p.y)<3.2f&&(q-p).sqrMagnitude<144).OrderBy(q=>(q-p).sqrMagnitude).ToArray();if(candidates.Length>0)moves[K(p)]=candidates[0];}}var mesh=shore.sharedMesh;int originalTriangles=mesh.triangles.Length,originalVertices=mesh.vertexCount;var points=mesh.vertices;int changed=0;float largest=0;for(int i=0;i<points.Length;i++){var world=shore.transform.TransformPoint(points[i]);Vector3 target;if(moves.TryGetValue(K(world),out target)){largest=Mathf.Max(largest,Vector3.Distance(world,target));points[i]=shore.transform.InverseTransformPoint(target);changed++;}}if(changed==0)throw new Exception("No matching existing promenade edge found");mesh.vertices=points;mesh.RecalculateBounds();mesh.RecalculateTangents();EditorUtility.SetDirty(mesh);if(shore.GetComponent<MeshCollider>()){shore.GetComponent<MeshCollider>().sharedMesh=null;shore.GetComponent<MeshCollider>().sharedMesh=mesh;}int removed=0;foreach(var f in roads.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.ToLower().Contains("beach promenade sidewalk joins")).ToArray()){UnityEngine.Object.DestroyImmediate(f.gameObject);removed++;}var prefab=PrefabUtility.LoadPrefabContents("Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab");var source=prefab.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Canal1");source.sharedMesh=mesh;if(source.GetComponent<MeshCollider>())source.GetComponent<MeshCollider>().sharedMesh=mesh;foreach(var f in prefab.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.ToLower().Contains("beach promenade sidewalk joins")).ToArray())UnityEngine.Object.DestroyImmediate(f.gameObject);PrefabUtility.SaveAsPrefabAsset(prefab,"Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab");PrefabUtility.UnloadPrefabContents(prefab);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,new Vector3(141.43f,36.25f,-83.49f),new Vector3(127.34f,2.14f,-4.63f),"Existing-Canal-Mesh-Joined-To-Sidewalk"});File.WriteAllText("FinalEnvironmentRoadReview/JoinExistingCanalEdge.txt","SUCCESS existing Canal1 mesh edge moved directly onto existing sidewalk; moved vertices="+changed+" maximum shift="+largest+"m; vertex count unchanged="+(originalVertices==mesh.vertexCount)+" triangle count unchanged="+(originalTriangles==mesh.triangles.Length)+"; separate filler objects removed="+removed+"; no new mesh/object/material/texture; scene/prefab/collider saved.");}}
